INSERT INTO public.trip_rand_spots (slug,name,prefecture,area,category,description,recommendation,address,access,parking,hours,fees,season,cautions,stay_minutes,tags,source_url,source_name,extra_sources,verified_on,nagoya_minutes_min,nagoya_minutes_max,travel_note,latitude,longitude,location_source_url,parking_free,scenic_road,drive_highlight) VALUES
('irago','伊良湖岬','愛知県','田原・渥美半島','海・湖','渥美半島の先端にある岬。白い灯台と海を眺めながら遊歩道を歩けます。','半島を走った先で、海風を感じる散歩を。恋路ヶ浜とあわせて巡る海沿いドライブに。','愛知県田原市伊良湖町古山','東名高速・豊川ICから車で約90分。','恋路ヶ浜駐車場を利用可。124台。','無休。','公式ページに見学料金の記載なし。','通年。晴れた日の夕景も見どころ。','灯台へは徒歩移動。海沿いの風と天候を確認。',60,ARRAY['灯台','夕日','海岸散歩']::text[],'https://aichinow.pref.aichi.jp/spots/detail/48/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',150,180,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',34.579923,137.016342,'https://aichinow.pref.aichi.jp/spots/detail/48/',NULL,FALSE,'半島を走った先で、海風を感じる散歩を。恋路ヶ浜とあわせて巡る海沿いドライブに。'),
('noma','野間埼灯台','愛知県','美浜・知多半島','海・湖','知多半島の西岸に立つ白い灯台。伊勢湾へ沈む夕日を眺められます。','知多半島の海岸ドライブでひと休み。夕方の写真散歩にも。','愛知県知多郡美浜町小野浦岩成20-1','南知多道路・美浜ICから約20分。','近くに有料駐車場あり。','無休・見学自由。','見学自由。駐車料金別。','通年。夕景。','路上駐車を避け、周辺駐車場を利用。',30,ARRAY['灯台','夕日','写真']::text[],'https://www.aichinow.pref.aichi.jp/spots/detail/115/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',60,90,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',34.757763,136.844479,'https://www.aichinow.pref.aichi.jp/spots/detail/115/',NULL,FALSE,'知多半島の海岸ドライブでひと休み。夕方の写真散歩にも。'),
('takeshima','竹島','愛知県','蒲郡・三河湾','海・湖','三河湾の小島へ橋を渡って歩けるスポット。島の自然や八百富神社を巡れます。','車を降りて海を近くに感じたい日に。蒲郡の海辺散策の目的地に。','愛知県蒲郡市竹島町3-15','竹島園地から橋を歩いて渡る。車の経路は地図で確認。','竹島園地駐車場約200台。平日無料、土日祝などは有料。','公式ページに散策時間の指定なし。','散策無料。祈祷・駐車料金別。','通年。','島内には岩場があり、歩きやすい靴で。',60,ARRAY['島','神社','海岸散歩']::text[],'https://aichinow.pref.aichi.jp/spots/detail/137/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',70,100,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',34.810649,137.231752,'https://aichinow.pref.aichi.jp/spots/detail/137/',TRUE,FALSE,'車を降りて海を近くに感じたい日に。蒲郡の海辺散策の目的地に。'),
('sangane','三ヶ根山スカイライン','愛知県','西尾・蒲郡','絶景道路','三ヶ根山の尾根を走る約5.1kmの有料道路。展望地点から三河湾を見渡せます。','走る時間そのものを楽しむ日に。展望駐車場で景色を眺めるドライブに。','愛知県西尾市東幡豆町入会山1-236（料金事務所）','音羽蒲郡ICから約40分。','山頂・第1・第2駐車場、合計110台。','8:00～20:00。通常20:00～翌8:00は通行禁止。','普通車420円、二輪280円（調査時の観光サイト掲載）。最新料金は道路公社で確認。','6月のあじさい、春のスイセン、晴れた日の眺望。','天候・通行規制・営業時間を出発前に確認。軽車両等は通行不可。',60,ARRAY['パノラマ','花','山道']::text[],'https://aichinow.pref.aichi.jp/spots/detail/123/','Aichi Now（愛知県公式観光サイト）','[{"name":"愛知県道路公社","url":"https://www.aichi-dourokousha.or.jp/rosen/kousha/三ヶ根山スカイライン/"}]'::jsonb,'2026-10-10',80,110,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',34.815615,137.159307,'https://aichinow.pref.aichi.jp/spots/detail/123/',NULL,TRUE,'走る時間そのものを楽しむ日に。展望駐車場で景色を眺めるドライブに。'),
('mikawawan','三河湾スカイライン','愛知県','幸田・蒲郡','絶景道路','幸田町深溝から国坂峠へ続く観光道路の愛称。山の尾根から三河湾を望めます。','海と山の風景を一度に楽しむドライブに。車窓を味わいたい日に。','愛知県額田郡幸田町深溝～蒲郡市豊岡町','県道525号蒲郡環状線。入口と経路は地図で確認。','観光サイトの駐車場欄は「無し」。','通行規制を確認。','通行無料。','通年。晴天時の三河湾の眺望。','台風等による通行止めの可能性あり。道路上に駐車しない。',45,ARRAY['パノラマ','山道','無料道路']::text[],'https://aichinow.pref.aichi.jp/spots/detail/123/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',70,100,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',34.8673579,137.2169061,'https://www.openstreetmap.org/way/174467834',NULL,TRUE,'海と山の風景を一度に楽しむドライブに。車窓を味わいたい日に。'),
('korankei','香嵐渓','愛知県','豊田・足助','山・自然','巴川沿いの渓谷。秋の紅葉に加え、春のカタクリなど季節の自然を楽しめます。','山あいの散歩と足助の町歩きを楽しむ日に。紅葉以外の季節も候補に。','愛知県豊田市足助町飯盛','猿投グリーンロード・力石ICから約15分、豊田勘八ICから約20分。','有料駐車場670台。掲載料金500円、11月1,000円。','散策自由。','散策自由。駐車料金別。','秋の紅葉、3月下旬～4月上旬のカタクリ。','紅葉期は混雑を見込んで余裕を持つ。イベント詳細は公式サイトを確認。',120,ARRAY['紅葉','渓谷','町歩き']::text[],'https://aichinow.pref.aichi.jp/spots/detail/1021/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',60,90,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.130327,137.313232,'https://aichinow.pref.aichi.jp/spots/detail/1021/',NULL,FALSE,'山あいの散歩と足助の町歩きを楽しむ日に。紅葉以外の季節も候補に。'),
('chausuyama','茶臼山高原','愛知県','豊根・奥三河','山・自然','愛知と長野の県境に広がる高原。芝桜や新緑、紅葉など四季の景色が魅力です。','街を離れて高原の空気を感じる一日に。山道を走って広い景色を眺める旅に。','愛知県北設楽郡豊根村坂宇場御所平70-185','名古屋IC・豊川ICからそれぞれ約2時間。','普通車1,000台。通常無料、芝桜期間は有料。','施設・季節による。木曜休み（イベント期間は無休）。','アクティビティ・リフト等は別料金。公式サイトで確認。','春の芝桜、夏の新緑、秋の紅葉、冬の雪景色。','冬の道路状況と各施設の営業状況を確認。',120,ARRAY['高原','花','紅葉']::text[],'https://aichinow.pref.aichi.jp/spots/detail/140/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',150,180,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.22012,137.655034,'https://aichinow.pref.aichi.jp/spots/detail/140/',TRUE,FALSE,'街を離れて高原の空気を感じる一日に。山道を走って広い景色を眺める旅に。'),
('inuyama','犬山城','愛知県','犬山・尾張','街・文化','木曽川沿いの高台にある国宝の城。天守から川や周辺の景色を見渡せます。','城下町散策と眺望を楽しむドライブに。歴史や街歩きが好きな日に。','愛知県犬山市犬山北古券65-2','小牧IC・小牧東IC・岐阜各務原ICから約25分。','周辺駐車場の位置・料金は現地公式案内で確認。今回の調査で詳細未確認。','9:00～17:00、入場16:30まで。','一般1,000円、小中学生200円（調査時掲載）。','通年。','城内は階段あり。混雑時は時間に余裕を。',120,ARRAY['城','町歩き','川の景色']::text[],'https://aichinow.pref.aichi.jp/spots/detail/20/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',45,65,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.388332,136.939269,'https://aichinow.pref.aichi.jp/spots/detail/20/',NULL,FALSE,'城下町散策と眺望を楽しむドライブに。歴史や街歩きが好きな日に。'),
('tokoname','やきもの散歩道','愛知県','常滑・知多半島','街・文化','窯や煙突、土管を使った坂道など、焼きものの街ならではの路地を巡る散策コースです。','知多半島ドライブに街歩きやカフェの時間を加えたい日に。','愛知県常滑市栄町3-8（陶磁器会館・案内所）','知多横断道路・常滑ICから約5分。','散歩道駐車場約45台・8時間300円、案内所駐車場約40台・全日500円（調査時掲載）。','散策自由。各店舗・施設の定休日は個別確認。','散策無料。見学施設や体験等は別料金。','通年。','坂道や細い路地あり。Aコース約1.6km・約1時間。',90,ARRAY['町歩き','焼きもの','カフェ']::text[],'https://www.aichinow.pref.aichi.jp/spots/detail/33/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',45,65,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',34.890575,136.839471,'https://www.aichinow.pref.aichi.jp/spots/detail/33/',NULL,FALSE,'知多半島ドライブに街歩きやカフェの時間を加えたい日に。'),
('tsukechi','付知峡','岐阜県','中津川・東濃','山・自然','澄んだ川と滝を楽しめる渓谷。遊歩道を歩き、森林の風景に触れられます。','新緑や紅葉を見に山あいへ走る日に。歩く時間をゆっくり取る自然ドライブに。','岐阜県中津川市付知町1区下浦地内','中央道・中津川ICから約50分。','利用場所・料金は付知町観光協会で確認。今回の調査で詳細未確認。','営業・遊歩道状況は観光協会で確認。','公式スポットページに料金の記載なし。','春の新緑、夏の滝、秋の紅葉。','冬は凍結・足元の滑りに注意。道路・遊歩道の最新状況を確認。',90,ARRAY['渓谷','滝','紅葉']::text[],'https://www.kankou-gifu.jp/spot/detail_5700.html','岐阜の旅ガイド（岐阜県観光連盟）','[]'::jsonb,'2026-10-10',120,150,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.698321,137.4414374,'https://www.kankou-gifu.jp/spot/detail_5700.html',NULL,FALSE,'新緑や紅葉を見に山あいへ走る日に。歩く時間をゆっくり取る自然ドライブに。'),
('magome','馬籠宿','岐阜県','中津川・東濃','街・文化','石畳の坂道に沿って宿場の町並みが続きます。島崎藤村ゆかりの場所としても知られます。','山の景色と歴史のある町歩きを楽しみたい日に。散策を目的にした日帰り旅に。','岐阜県中津川市馬籠','詳細な車の経路は地図で確認。市の公式観光案内を参照。','駐車場の位置・料金は馬籠観光協会で確認。今回の調査で詳細未確認。','各店舗・資料館の営業は個別確認。','資料館・飲食等は別料金。','通年。','坂道と石畳あり。歩きやすい靴で。',90,ARRAY['宿場町','町歩き','歴史']::text[],'https://www.city.nakatsugawa.lg.jp/soshikikarasagasu/kankoka/5/2/756.html','中津川市公式サイト','[{"name":"岐阜の旅ガイド・馬籠宿一覧","url":"https://www.kankou-gifu.jp/spot/index_1_2____0__馬籠宿___.html"}]'::jsonb,'2026-10-10',90,120,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.526549,137.5674758,'https://www.openstreetmap.org/node/10914014076',NULL,FALSE,'山の景色と歴史のある町歩きを楽しみたい日に。散策を目的にした日帰り旅に。'),
('yoro','養老の滝','岐阜県','養老・西濃','山・自然','養老公園にある高さ約30mの滝。滝へ向かう道も自然散策を楽しめます。','公園でゆっくり歩いて気分転換する日に。ドライブと軽い散策を組み合わせて。','岐阜県養老郡養老町養老公園','大垣ICから約25分（岐阜県案内）。入口駐車場から滝へ徒歩約30分。','養老の滝入口駐車場。最新料金・利用時間は公園で確認。','公園の最新案内を確認。','滝は無料エリア。周辺有料施設・駐車料金は別途確認。','通年。紅葉の季節も見どころ。','駐車場から約1.2km歩く。滝まで車で直接入る目的地ではありません。',90,ARRAY['滝','公園','紅葉']::text[],'https://www.yoro-park.com/facility-map/yoro-falls/index.html','養老公園公式サイト','[{"name":"岐阜県・交通アクセス","url":"https://www.pref.gifu.lg.jp/page/3157.html"}]'::jsonb,'2026-10-10',50,75,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.2821734,136.5357423,'https://www.yoro-park.com/facility-map/yoro-falls/index.html',NULL,FALSE,'公園でゆっくり歩いて気分転換する日に。ドライブと軽い散策を組み合わせて。'),
('gozaisho','御在所岳・湯の山温泉','三重県','菰野・鈴鹿山麓','山・自然','山麓の湯の山温泉からロープウェイで山上へ。四季の山の景色を楽しめます。','山麓までドライブし、ロープウェイで景色を楽しむ日に。温泉と組み合わせても。','三重県三重郡菰野町（御在所ロープウェイ山麓）','四日市ICから湯の山温泉方面へ約20分。','ロープウェイの公式アクセスページで駐車場の最新情報を確認。','ロープウェイの季節別営業時間・運行状況を確認。','ロープウェイ・駐車・温泉等は有料。最新料金は各施設で確認。','春の花、秋の紅葉、冬の樹氷。','車は山麓まで。中道登山コースは2025年5月25日以降通行止めとの掲載あり。運行・登山規制を確認。',150,ARRAY['ロープウェイ','温泉','紅葉']::text[],'https://www.kankomie.or.jp/spot/1579','観光三重（三重県観光連盟）','[{"name":"御在所ロープウエイ・アクセス","url":"https://www.gozaisho.co.jp/access/"}]'::jsonb,'2026-10-10',60,85,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.016355066873906,136.44609550838038,'https://www.gozaisho.co.jp/access/',NULL,FALSE,'山麓までドライブし、ロープウェイで景色を楽しむ日に。温泉と組み合わせても。'),
('aoyama','青山高原','三重県','伊賀・津','絶景道路','風車が並ぶ高原を道路が走ります。草原や展望の風景を楽しめるエリアです。','風車と空が広がる景色を眺めながら走りたい日に。高原散策も組み合わせて。','三重県伊賀市・津市の青山高原一帯','青山高原道路。入口と当日の道路状況は地図・現地案内で確認。','展望地点の利用可能な駐車場は現地公式案内で確認。今回の調査で詳細未確認。','道路・施設の規制を確認。','公式特集に道路料金の記載なし。','春の花、夏の草原、秋のススキ。','冬の道路状況、強風や霧、通行規制を確認。',90,ARRAY['高原','風車','パノラマ']::text[],'https://www.kankomie.or.jp/special/iganabari/spot/spotD','観光三重（三重県観光連盟）','[]'::jsonb,'2026-10-10',120,150,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',34.6897044,136.2760854,'https://www.openstreetmap.org/node/7114636264',NULL,TRUE,'風車と空が広がる景色を眺めながら走りたい日に。高原散策も組み合わせて。'),
('kanzanji','浜名湖・舘山寺','静岡県','浜松・浜名湖','海・湖','浜名湖畔の温泉エリア。湖の景色と門前通りの散策、地元グルメを楽しめます。','湖沿いドライブに散歩と食事を加えたい日に。うなぎや温泉を目当てにしても。','静岡県浜松市中央区舘山寺町1832-1（観光協会）','東名・舘山寺スマートICから約5分。','観光協会駐車場は普通車150台・無料（調査時掲載）。ほか周辺公共駐車場あり。','飲食店・温泉など施設ごとに確認。','飲食・温泉等は別料金。','通年。','施設ごとの定休日と日帰り入浴の受付時間を確認。',120,ARRAY['湖','温泉','グルメ']::text[],'https://www.kanzanji.gr.jp/access','舘山寺温泉観光協会','[{"name":"舘山寺門前通り公式","url":"https://kanzanji-monzen.com/"}]'::jsonb,'2026-10-10',90,120,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',34.761592479942045,137.61334847642993,'https://www.kanzanji.gr.jp/access',TRUE,FALSE,'湖沿いドライブに散歩と食事を加えたい日に。うなぎや温泉を目当てにしても。'),
('nakatajima','中田島砂丘','静岡県','浜松・遠州灘','海・湖','遠州灘に面した砂丘。風が砂に描く風紋など、海辺の景観を楽しめます。','広い空と砂浜を眺めて気分転換する日に。浜松方面への海沿いドライブの目的地に。','静岡県浜松市中央区中田島町','東名・浜松ICから約25分。','周辺公園の駐車場の利用条件は管理者の案内で確認。今回の調査で詳細未確認。','立入可能範囲と現地案内を確認。','公式スポットページに料金の記載なし。','通年。冬の風の強い朝には風紋が見られることも。','砂の上を歩く。風・天候と立入制限を確認。',60,ARRAY['砂丘','海岸散歩','写真']::text[],'https://www.hamamatsu-japan.com/en/sightseeing/2403/','浜松・浜名湖ツーリズムビューロー','[]'::jsonb,'2026-10-10',110,140,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',34.6605872,137.7416332,'https://www.openstreetmap.org/way/935429778',NULL,FALSE,'広い空と砂浜を眺めて気分転換する日に。浜松方面への海沿いドライブの目的地に。'),
('iwayado','岩屋堂公園','愛知県','瀬戸・尾張','山・自然','天然の大岩でできた岩屋堂や渓流を巡れる公園。新緑や紅葉を楽しめます。','名古屋から山の空気を感じる短めのドライブに。川沿いの散歩と組み合わせて。','愛知県瀬戸市岩屋町','公園までの経路は地図で確認。','無料駐車場と民間有料駐車場あり。紅葉期などは料金・規制を確認。','散策自由。イベントは開催案内を確認。','公園散策無料。駐車料金は時期・駐車場による。','春の桜、夏の渓流、秋の紅葉。','散策路は歩きやすい靴で。紅葉時期の駐車・交通規制に注意。',90,ARRAY['渓流','紅葉','近場']::text[],'https://aichinow.pref.aichi.jp/spots/detail/174/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',50,75,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.240161,137.144812,'https://aichinow.pref.aichi.jp/spots/detail/174/',TRUE,FALSE,'名古屋から山の空気を感じる短めのドライブに。川沿いの散歩と組み合わせて。'),
('jokoji','定光寺','愛知県','瀬戸・尾張','街・文化','森に囲まれた寺院。歴史ある建物と紅葉、展望地点からの眺めを楽しめます。','近場で静かな山の景色と歴史に触れる日に。階段を歩く時間もゆっくり取って。','愛知県瀬戸市定光寺町373','車の経路は地図で確認。駐車場から徒歩で境内へ。','駐車場あり。利用条件・料金は公式案内を確認。','拝観・施設の営業は現地公式案内を確認。','境内無料。源敬公廟などは別途確認。','新緑と秋の紅葉。','本堂へ向かう階段あり。無理のない散策計画で。',60,ARRAY['寺院','紅葉','近場']::text[],'https://aichinow.pref.aichi.jp/spots/detail/959/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',45,65,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.280336,137.090971,'https://aichinow.pref.aichi.jp/spots/detail/959/',NULL,FALSE,'近場で静かな山の景色と歴史に触れる日に。階段を歩く時間もゆっくり取って。'),
('kariya','刈谷ハイウェイオアシス','愛知県','刈谷・西三河','街・文化','食事や買い物、観覧車、温泉、公園が集まる施設。高速道路と一般道の両方から利用できます。','遠出をしない日でも、食事と温泉や公園を楽しむドライブに。','愛知県刈谷市東境町吉野55番地','伊勢湾岸道・刈谷PAと一般道から入場可能。スマートIC入口利用時はPAに入れない案内あり。','高速道路側約700台、一般道側約1,300台。無料。','施設ごとに異なる。PA店舗7:00～22:00など。','入場無料。観覧車・温泉等は有料。','通年。','高速道路側と一般道側の入口を地図で確認。各施設の休業日を確認。',120,ARRAY['温泉','グルメ','近場']::text[],'https://aichinow.pref.aichi.jp/spots/detail/40/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',35,55,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.041084,137.048259,'https://aichinow.pref.aichi.jp/spots/detail/40/',TRUE,FALSE,'遠出をしない日でも、食事と温泉や公園を楽しむドライブに。'),
('shinmaiko','新舞子マリンパーク','愛知県','知多・知多半島','海・湖','人工海浜や芝生広場を備えた海辺の公園。海を眺めて散策やピクニックを楽しめます。','名古屋から海を見に行く短いドライブに。砂浜と広場でのんびり過ごして。','愛知県知多市緑浜町2','車での経路は地図と公式アクセス案内を確認。','駐車場あり。土日祝と海水浴場開設期間は有料との公式案内。','管理施設9:00～17:00。各エリアの利用時間は公式案内を確認。','公園散策は無料。駐車料金や施設利用料金は別途確認。','通年の散策。海水浴は指定の開設期間のみ。','海水浴・釣り・ドッグランは各エリアの利用ルールを確認。',90,ARRAY['海岸散歩','公園','近場']::text[],'https://www.port-of-nagoya.jp/kanko/kankoshisetsu/1000895.html','名古屋港管理組合公式サイト','[{"name":"新舞子マリンパーク公式","url":"https://www.marine-park.jp/"}]'::jsonb,'2026-10-10',40,60,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',34.954882,136.821566,'https://www.port-of-nagoya.jp/kanko/kankoshisetsu/1000895.html',NULL,FALSE,'名古屋から海を見に行く短いドライブに。砂浜と広場でのんびり過ごして。'),
('meijimura','博物館 明治村','愛知県','犬山・尾張','街・文化','明治時代を中心とした建物を移築・保存した野外博物館。広い敷地を歩いて巡れます。','ドライブの先で一日ゆっくり建築や歴史を楽しみたい日に。','愛知県犬山市内山1','車の入口と駐車場は公式アクセス案内・地図で確認。','普通車900台。掲載料金1回1,000円。最新料金は公式で確認。','季節・イベントにより変動。入村は閉村30分前まで。','入村有料。調査時掲載の大人料金2,500円。乗り物等は別料金。','通年。','広い園内を歩く。休村日と閉村時間を確認。',240,ARRAY['建築','歴史','町歩き']::text[],'https://aichinow.pref.aichi.jp/spots/detail/22/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',45,65,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.3406604,136.988472,'https://aichinow.pref.aichi.jp/spots/detail/22/',NULL,FALSE,'ドライブの先で一日ゆっくり建築や歴史を楽しみたい日に。'),
('kuragaike','鞍ケ池公園','愛知県','豊田・西三河','山・自然','池を中心に動物園、芝生広場、遊歩道などがある緑豊かな公園です。','山あいまで走ってピクニックや池の周りの散歩を楽しむ日に。','愛知県豊田市矢並町法沢714-5','鞍ケ池スマートICから約3分、豊田松平ICから約15分。','普通車874台、無料との掲載。','9:00～17:00、動物園10:00～16:30。施設により休業日あり。','基本無料。ボート・パークトレイン等は有料。','通年。','年末・施設別休業日を確認。園内の起伏を見込んで歩きやすい靴で。',120,ARRAY['公園','動物','ピクニック']::text[],'https://aichinow.pref.aichi.jp/spots/detail/1509/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',50,70,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.098496,137.216901,'https://aichinow.pref.aichi.jp/spots/detail/1509/',TRUE,FALSE,'山あいまで走ってピクニックや池の周りの散歩を楽しむ日に。'),
('toyotamuseum','トヨタ博物館','愛知県','長久手・尾張','街・文化','日本や世界の自動車と、クルマにまつわる文化資料を展示する博物館です。','ドライブとクルマの歴史を楽しむ日に。天気を気にせず見学したい日にも。','愛知県長久手市横道41-100','公式アクセス案内と地図で経路を確認。','乗用車320台、無料との掲載。','9:30～17:00、入館16:30まで。月曜（祝日は翌日）と年末年始休館。','調査時掲載の大人料金1,200円。最新料金は公式を確認。','通年。','休館日と特別展示の開催状況を確認。',120,ARRAY['博物館','クルマ','雨の日']::text[],'https://aichinow.pref.aichi.jp/spots/detail/26/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',35,55,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.172734,137.058073,'https://aichinow.pref.aichi.jp/spots/detail/26/',TRUE,FALSE,'ドライブとクルマの歴史を楽しむ日に。天気を気にせず見学したい日にも。'),
('aichiranch','愛知牧場','愛知県','日進・尾張','山・自然','動物とのふれあいや季節の花、牧場の乳製品などを楽しめる観光牧場です。','短いドライブで緑と動物を楽しみたい日に。花畑やソフトクリームも寄り道の楽しみに。','愛知県日進市米野木町南山977','車の経路と駐車場入口は地図・公式案内を確認。','普通車500台。曜日・季節で有料。最新料金は公式を確認。','9:00～17:00。どうぶつ広場は時間別。火曜休み（特別期間等を除く）。','牧場入場無料。どうぶつ広場・体験等は有料。','季節の花。通年の動物ふれあい。','火曜は花畑も入場不可との案内。体験は予約要否を確認。',120,ARRAY['動物','花','近場']::text[],'https://aichinow.pref.aichi.jp/spots/detail/969/','Aichi Now（愛知県公式観光サイト）','[]'::jsonb,'2026-10-10',35,55,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.13026,137.08709,'https://aichinow.pref.aichi.jp/spots/detail/969/',NULL,FALSE,'短いドライブで緑と動物を楽しみたい日に。花畑やソフトクリームも寄り道の楽しみに。'),
('satoyama','ぎふ清流里山公園','岐阜県','美濃加茂・中濃','山・自然','里山の自然や散策、体験、食事を楽しめる公園。温浴施設もあります。','名古屋から北へ走って、散歩や体験をゆっくり楽しむ日帰りドライブに。','岐阜県美濃加茂市山之上町2292-1','東海環状道・美濃加茂ICを降りてすぐ。','駐車場あり。利用条件は公園公式案内を確認。','季節による。県掲載では3～11月9:00～18:00、冬10:00～17:00。現行公式案内を優先。','入園無料。体験・温浴などは別料金。','通年。','冬期の休園日、各体験・温浴施設の営業を確認。',150,ARRAY['里山','体験','温泉']::text[],'https://satoyama-park.gifu.jp/','ぎふ清流里山公園公式サイト','[{"name":"岐阜県公式・アクセス","url":"https://www.pref.gifu.lg.jp/page/17850.html"}]'::jsonb,'2026-10-10',60,85,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.474873,137.033673,'https://satoyama-park.gifu.jp/',NULL,FALSE,'名古屋から北へ走って、散歩や体験をゆっくり楽しむ日帰りドライブに。'),
('nabana','なばなの里','三重県','桑名・長島','山・自然','季節の花や期間限定のイルミネーションを楽しめる施設です。','名古屋から花や夜の景色を見に行くドライブに。帰りの時間も見込んでゆっくりと。','三重県桑名市長島町駒江漆畑270','季節別の公式アクセス案内・地図で経路を確認。','無料大駐車場5,700台との公式案内。','時期・曜日・イベントによる。公式営業カレンダーを確認。','入村有料。料金・金券の有無は時期別の公式案内を確認。','季節の花と開催期間中のイルミネーション。','イルミネーションは開催期間限定。混雑・営業日を確認。',150,ARRAY['花','イルミネーション','近場']::text[],'https://www.nagashima-onsen.co.jp/nabana/access/index.html','ナガシマリゾート・なばなの里公式','[]'::jsonb,'2026-10-10',30,50,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.081633,136.702875,'https://www.nagashima-onsen.co.jp/nabana/access/index.html',TRUE,FALSE,'名古屋から花や夜の景色を見に行くドライブに。帰りの時間も見込んでゆっくりと。'),
('kisosansen','木曽三川公園センター','岐阜県','海津・西濃','山・自然','木曽三川の風景や、花壇・広場を楽しめる国営公園の拠点です。','川沿いを走って広い景色の中で散歩する日に。季節の花を見に行く近場の旅に。','岐阜県海津市海津町油島255-3','公園公式アクセス案内・地図で経路を確認。','駐車場あり。利用時間と条件は公式案内を確認。','開園時間・休園日は季節による。公式案内を確認。','公園入園無料。展望タワー等は別料金。','春のチューリップなど季節の花、冬のイルミネーション。','催事の開催日と開園時間を確認。',90,ARRAY['公園','花','川の景色']::text[],'https://www.kisosansenkoen.jp/~center/','国営木曽三川公園公式サイト','[]'::jsonb,'2026-10-10',40,60,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.1470461,136.6673792,'https://www.openstreetmap.org/relation/14979947',NULL,FALSE,'川沿いを走って広い景色の中で散歩する日に。季節の花を見に行く近場の旅に。'),
('tower138','138タワーパーク','愛知県','一宮・尾張','山・自然','ツインアーチ138をシンボルに、木曽川沿いの広場や季節の花を楽しめる公園です。','名古屋から気軽に広い空を見に行く日に。散歩やピクニックのドライブに。','愛知県一宮市光明寺浦崎21-3','公園公式アクセス案内・地図で経路を確認。','第2・第3駐車場などあり。利用条件は公園で確認。','公園・展望タワーの開園時間と休園日は公式案内を確認。','公園入園無料。展望タワー有料。','季節の花と、期間限定のイルミネーション。','タワーと公園の営業時間は別。イベント日は混雑を見込む。',90,ARRAY['公園','展望台','近場']::text[],'https://www.kisosansenkoen.jp/~tower138/m138sisetu.html','国営木曽三川公園公式サイト','[]'::jsonb,'2026-10-10',35,55,'名古屋駅周辺発・車で片道の編集上の概算。高速道路利用を含み、渋滞・休憩・駐車待ちは含みません。最新の経路と時間は地図で確認。',35.3577,136.80906,'https://www.openstreetmap.org/way/485875163',NULL,FALSE,'名古屋から気軽に広い空を見に行く日に。散歩やピクニックのドライブに。'),
